node -e '
import("./src/store.mjs").then(({searchFiles, writeUserFile}) => {
  const fs = require("node:fs"), os = require("node:os"), p = require("node:path");
  const base = fs.mkdtempSync(p.join(os.tmpdir(), "probe-"));
  const root = p.join(base, "alice"), other = p.join(base, "bob");
  writeUserFile(root, "a.txt", "secret");
  writeUserFile(other, "theirs.txt", "secret");
  try { searchFiles(root, "secret", { within: "a.txt" }); } catch (e) { console.log("within=file:", e.code, e.message); }
  fs.symlinkSync(p.join(other, "theirs.txt"), p.join(root, "leak.txt"), "file");
  console.log("symlinked file in root:", searchFiles(root, "secret"));
  try { console.log(searchFiles(p.join(base, "nope"), "x", { within: "docs" })); } catch (e) { console.log("missing root:", e.code); }
});'

npm test 2>&1 | tail -15; node --input-type=module -e '
