import { tmpdir } from "node:os"; import { join } from "node:path";
import { searchFiles, writeUserFile } from "./src/store.mjs";
const base = mkdtempSync(join(tmpdir(), "sec-"));
const root = join(base, "alice"); const outside = join(base, "outside.txt");
writeFileSync(outside, "TOP-SECRET-TOKEN");
writeUserFile(root, "mine.txt", "x");
symlinkSync(outside, join(root, "leak.txt"), "file");
console.log("symlinked file searched:", JSON.stringify(searchFiles(root, "SECRET-TOK")));
try { searchFiles(root, "x", { within: "nope" }); } catch (e) { console.log("ENOENT message:", e.message); }
try { searchFiles(root, "x", { within: "../bob<script>" }); } catch (e) { console.log("escape message:", e.message); }
'
